inline Rva003DF250PathfindCell *Pathfinder::getCell(Int layer, Int x, Int y)
{
    if (x >= m_extent.lo.x && x <= m_extent.hi.x && y >= m_extent.lo.y && y <= m_extent.hi.y) {
        if (layer > 1 && layer <= 15) {
            Rva003DF250PathfindCell *cell = m_layers[layer].getCell(x, y);
            if (cell) return cell;
        }
        return &m_map[x][y];
    }
    return 0;
}

bool Pathfinder::Rva003DF250(Object *object, Coord3D *position)
{
    Int radius;
    Bool centered;
    getRadiusAndCenter(object, radius, centered);

    Coord3D local = *position;
    if (!centered) {
        local.x += *(const float *)0x01075344;
        local.y += *(const float *)0x01075344;
    }
    int selectedLayer = s_terrain->getLayerForDestination(object, position);
    Rva003DF250CellIndex cellIndex;
    worldToCell(&local, &cellIndex);
    adjustCoordToCell(cellIndex.x, cellIndex.y, centered, *position, selectedLayer);

    Int endDelta = radius;
    if (centered) endDelta++;
    ObjectID selfID = (ObjectID)object->m_id;
    for (int x = cellIndex.x - radius; x < cellIndex.x + endDelta; ++x) {
        for (int y = cellIndex.y - radius; y < cellIndex.y + endDelta; ++y) {
            if (x < m_extent.lo.x || x > m_extent.hi.x || y < m_extent.lo.y || y > m_extent.hi.y)
                return false;
            Rva003DF250PathfindCell *cell = getCell(selectedLayer, x, y);
            if (!cell)
                return false;

            unsigned int flags = cell->m_packed;
            if ((flags & 7) == 5)
                return false;
            if ((flags & (1u << 21)) && object->bfmeIsComputerControlled())
                return false;
            flags = cell->m_packed;
            unsigned int type = flags & 7;
            if (type == 4 || type == 5 || type == 6)
                return false;
            if (flags & 0x38) {
                Rva003DF250PathfindCellInfo *info = cell->m_info;
                ObjectID relatedID = info ? info->m_posUnitID : INVALID_ID;
                if (relatedID != selfID && relatedID != 0) {
                    if (!object->isKindOf(0x7c))
                        return false;
                    Object *related = s_logic->findObjectByID(relatedID);
                    if (related && !related->isKindOf(8))
                        return false;
                }
                relatedID = info ? info->m_goalUnitID : INVALID_ID;
                if (relatedID != selfID && relatedID != 0) {
                    Object *related = s_logic->findObjectByID(relatedID);
                    if (related) {
                        if (related->isKindOf(0x6c)) {
                            if (!object->isKindOf(0x6c))
                                continue;
                        }
                        if (!related->isKindOf(8) || !object->isKindOf(0x7c)) {
                            return false;
                        }
                    }
                }
            }
        }
    }
    return true;
}
